-- === STEP 5: PAYMENTS ===

-- === STEP 6: VERIFY ===
SELECT
  (SELECT COUNT(*) FROM customers) as total_customers,
  (SELECT COUNT(*) FROM customers WHERE status = 'يعمل') as active_customers,
  (SELECT COUNT(*) FROM payments) as total_payments,
  (SELECT ROUND(COALESCE(SUM(amount),0)) FROM payments) as total_amount;